import { defineConfig } from 'vitest/config'

const testTimeout = process.env.CI ? 20_000 : 5_000

export default defineConfig({
	test: {
		name: 'node-unit',
		environment: 'node',
		include: ['**/*.node.test.ts'],
		testTimeout,
		hookTimeout: testTimeout,
		fileParallelism: false,
		clearMocks: true,
	},
})

{
  "name": "@kody-smoke/counter",
  "version": "1.0.0",
  "description": "Durable counter backed by packageStorage(), with a recurring tick job.",
  "exports": {
    ".": "./status.js",
    "./increment": "./increment.js",
    "./tick": "./tick.js"
  },
  "kody": {
    "jobs": {
      "tick": {
        "entry": "./tick.js",
        "schedule": {
          "type": "interval",
          "every": "1m"
        },
        "description": "Increments the tick counter every minute."
      },
      "backfill": {
        "entry": "./tick.js",
        "schedule": {
          "type": "once",
          "runAt": "2020-01-01T00:00:00Z"
        },
        "description": "One-shot job whose runAt is already in the past; runs on the next dispatch."
      }
    }
  }
}

{
  "name": "@kody-smoke/http-probe",
  "version": "1.0.0",
  "description": "Calls an HTTP endpoint with a secret placeholder header. Demonstrates host-gated secret injection.",
  "exports": {
    ".": "./probe.js",
    "./provider": "./provider-probe.js"
  },
  "kody": {}
}

{
  "name": "@kody-smoke/inbox-hooks",
  "version": "1.0.0",
  "description": "Records inbound webhook deliveries and email events in packageStorage(); exercised by smoke/webhooks.mjs and smoke/email.mjs.",
  "exports": {
    ".": "./status.js",
    "./github": "./github.js",
    "./stripe": "./stripe.js",
    "./plain": "./plain.js"
  },
  "kody": {
    "webhooks": [
      {
        "name": "github",
        "export": "./github",
        "responseMode": "ack",
        "inputMode": "request",
        "rateLimitPerMinute": 120,
        "verification": {
          "type": "hmac-sha256",
          "header": "x-hub-signature-256",
          "prefix": "sha256=",
          "encoding": "hex",
          "secretName": "githubWebhookSecret",
          "signedPayload": "body"
        },
        "replay": {
          "deliveryIdHeader": "x-github-delivery"
        },
        "description": "GitHub push/issue events; verified with the shared secret and deduplicated by delivery id."
      },
      {
        "name": "stripe",
        "export": "./stripe",
        "responseMode": "sync",
        "inputMode": "request",
        "rateLimitPerMinute": 5,
        "verification": {
          "type": "hmac-sha256",
          "header": "stripe-signature",
          "encoding": "hex",
          "secretName": "stripeWebhookSecret",
          "signedPayload": "timestamp.body"
        },
        "replay": {
          "timestampHeader": "stripe-signature",
          "timestampFormat": "stripe-signature",
          "toleranceSeconds": 300
        },
        "description": "Stripe events; Stripe-Signature t=/v1= verification with a 5 minute replay window."
      },
      {
        "name": "plain",
        "export": "./plain",
        "responseMode": "sync",
        "inputMode": "params",
        "description": "Unsigned JSON webhook; the body becomes the export's params and the return value is the HTTP response."
      }
    ],
    "subscriptions": {
      "email.message.received": {
        "handler": "./lib/on-email.js",
        "description": "Files every inbound email's id + subject."
      }
    }
  }
}

{
  "name": "@kody-smoke/oauth-client",
  "version": "1.0.0",
  "description": "Calls an API with createAuthenticatedFetch(integration) and records integration.auth.* events; exercised by smoke/integrations.mjs.",
  "exports": {
    ".": "./status.js",
    "./call": "./call.js"
  },
  "kody": {
    "subscriptions": {
      "integration.auth.succeeded": {
        "handler": "./lib/on-auth.js",
        "description": "Records every successful connect/refresh (metadata only)."
      },
      "integration.auth.failed": {
        "handler": "./lib/on-auth.js",
        "description": "Records refresh/connect failures so the owner can reconnect."
      }
    }
  }
}

{
  "name": "@kody-examples/onepassword-connect",
  "version": "1.0.0",
  "description": "Secret provider for a self-hosted 1Password Connect server: {{secret/1password:vaults/<vault>/items/<item>/fields/<field>}}.",
