    ".": "./status.js",
    "./secretProvider": "./provider.js"
  },
  "kody": {
    "secretProvider": {
      "id": "1password",
      "description": "Resolves item fields from 1Password Connect; the item's website URLs become the allowed hosts."
    }
  }
}

{
  "name": "@kody-smoke/smoke-vault",
  "version": "1.0.0",
  "description": "Secret provider backed by the smoke suite's mock vault (smoke/secret-providers.mjs). Shows the provider contract end to end.",
  "exports": {
    ".": "./status.js",
    "./secretProvider": "./provider.js"
  },
