# Single-node kody-celld for a NAS, home server, or one VPS.
#
#   docker compose up -d
#   docker compose exec kody cat /data/kody.env     # admin token + master key
#
# Durable state (users, packages, secrets, jobs) lives in the `kody-data`
# volume. Back it up. `up` builds the image from this checkout when it is not
# present locally; `docker compose pull` fetches the prebuilt multi-arch image
# from ghcr.io instead. To upgrade: `docker compose pull && docker compose up -d`
# (or `git pull && docker compose up -d --build`); state and generated operator
# values are kept.
#
# Copy .env.example to .env to set KODY_PUBLIC_URL (the URL people will use,
# e.g. https://kody.home.example.com behind your reverse proxy) or to pin your
# own KODY_ADMIN_TOKEN / KODY_MASTER_KEY instead of the generated ones.
services:
  kody:
    build: .
    image: ${KODY_IMAGE:-ghcr.io/kentcdodds/kody-celld:latest}
    command: ['single']
    init: true
    restart: unless-stopped
    ports:
      - '${KODY_PORT:-8080}:8080'
    environment:
      KODY_PUBLIC_URL: ${KODY_PUBLIC_URL:-http://localhost:8080}
      KODY_ADMIN_TOKEN: ${KODY_ADMIN_TOKEN:-}
      KODY_MASTER_KEY: ${KODY_MASTER_KEY:-}
      KODY_MASTER_KEY_PREVIOUS: ${KODY_MASTER_KEY_PREVIOUS:-}
      KODY_ALLOW_INSECURE_SECRET_HOSTS: ${KODY_ALLOW_INSECURE_SECRET_HOSTS:-}
      # Limits and quota defaults (docs/operations.md); empty = built-in default.
      KODY_EXECUTE_TIMEOUT_MS: ${KODY_EXECUTE_TIMEOUT_MS:-}
      KODY_RUN_RETENTION_COUNT: ${KODY_RUN_RETENTION_COUNT:-}
      KODY_RUN_RETENTION_DAYS: ${KODY_RUN_RETENTION_DAYS:-}
      KODY_RUN_LOG_LIMIT: ${KODY_RUN_LOG_LIMIT:-}
      KODY_RESPONSE_LIMIT_BYTES: ${KODY_RESPONSE_LIMIT_BYTES:-}
      KODY_AUDIT_RETENTION_COUNT: ${KODY_AUDIT_RETENTION_COUNT:-}
      KODY_QUOTA_RUNS_PER_DAY: ${KODY_QUOTA_RUNS_PER_DAY:-}
      KODY_QUOTA_EXECUTE_MS_PER_DAY: ${KODY_QUOTA_EXECUTE_MS_PER_DAY:-}
      KODY_QUOTA_PACKAGES: ${KODY_QUOTA_PACKAGES:-}
      KODY_QUOTA_SECRETS: ${KODY_QUOTA_SECRETS:-}
      KODY_QUOTA_JOBS: ${KODY_QUOTA_JOBS:-}
      # AI, memories and semantic search (docs/ai.md); empty = off / lexical only.
      KODY_AI_PROVIDER: ${KODY_AI_PROVIDER:-}
      KODY_AI_BASE_URL: ${KODY_AI_BASE_URL:-}
      KODY_AI_API_KEY: ${KODY_AI_API_KEY:-}
      KODY_AI_CHAT_MODEL: ${KODY_AI_CHAT_MODEL:-}
      KODY_AI_EMBED_PROVIDER: ${KODY_AI_EMBED_PROVIDER:-}
      KODY_AI_EMBED_BASE_URL: ${KODY_AI_EMBED_BASE_URL:-}
      KODY_AI_EMBED_API_KEY: ${KODY_AI_EMBED_API_KEY:-}
      KODY_AI_EMBED_MODEL: ${KODY_AI_EMBED_MODEL:-}
      KODY_AI_EMBED_DIMENSIONS: ${KODY_AI_EMBED_DIMENSIONS:-}
      KODY_AI_TIMEOUT_MS: ${KODY_AI_TIMEOUT_MS:-}
      KODY_SEARCH_RERANK: ${KODY_SEARCH_RERANK:-}
      KODY_VECTOR_PROVIDER: ${KODY_VECTOR_PROVIDER:-}
      KODY_QDRANT_URL: ${KODY_QDRANT_URL:-}
      KODY_QDRANT_API_KEY: ${KODY_QDRANT_API_KEY:-}
      KODY_QDRANT_COLLECTION: ${KODY_QDRANT_COLLECTION:-}
      # Blob storage (docs/blobs.md); empty = celld R2 binding on the fleet bucket.
      KODY_BLOB_PROVIDER: ${KODY_BLOB_PROVIDER:-}
      KODY_BLOB_S3_ENDPOINT: ${KODY_BLOB_S3_ENDPOINT:-}
      KODY_BLOB_S3_BUCKET: ${KODY_BLOB_S3_BUCKET:-}
      KODY_BLOB_S3_REGION: ${KODY_BLOB_S3_REGION:-}
      KODY_BLOB_S3_ACCESS_KEY_ID: ${KODY_BLOB_S3_ACCESS_KEY_ID:-}
      KODY_BLOB_S3_SECRET_ACCESS_KEY: ${KODY_BLOB_S3_SECRET_ACCESS_KEY:-}
      KODY_BLOB_S3_PREFIX: ${KODY_BLOB_S3_PREFIX:-}
      KODY_BLOB_S3_FORCE_PATH_STYLE: ${KODY_BLOB_S3_FORCE_PATH_STYLE:-}
      KODY_BLOB_MAX_BYTES: ${KODY_BLOB_MAX_BYTES:-}
      KODY_BLOB_URL_TTL_SECONDS: ${KODY_BLOB_URL_TTL_SECONDS:-}
      KODY_QUOTA_BLOBS: ${KODY_QUOTA_BLOBS:-}
      KODY_QUOTA_BLOB_BYTES: ${KODY_QUOTA_BLOB_BYTES:-}
      KODY_MCP_CONTENT_LIMIT_BYTES: ${KODY_MCP_CONTENT_LIMIT_BYTES:-}
      # Browser rendering (docs/browser.md); empty = off. compose.browser.yaml adds browserless.
      KODY_BROWSER_PROVIDER: ${KODY_BROWSER_PROVIDER:-}
      KODY_BROWSER_URL: ${KODY_BROWSER_URL:-}
      KODY_BROWSER_TOKEN: ${KODY_BROWSER_TOKEN:-}
      KODY_BROWSER_CF_ACCOUNT_ID: ${KODY_BROWSER_CF_ACCOUNT_ID:-}
      KODY_BROWSER_TIMEOUT_MS: ${KODY_BROWSER_TIMEOUT_MS:-}
      KODY_BROWSER_ALLOW_PRIVATE_HOSTS: ${KODY_BROWSER_ALLOW_PRIVATE_HOSTS:-}
      # npm imports + package installs (docs/packages.md); empty = esm.sh, durable cache on. compose.esm.yaml adds a self-hosted CDN.
      KODY_NPM_IMPORTS: ${KODY_NPM_IMPORTS:-}
      KODY_ESM_CDN_URL: ${KODY_ESM_CDN_URL:-}
      KODY_NPM_CACHE_MAX_MB: ${KODY_NPM_CACHE_MAX_MB:-}
      KODY_NPM_CACHE_TTL_DAYS: ${KODY_NPM_CACHE_TTL_DAYS:-}
      KODY_PACKAGE_SOURCE_HOSTS: ${KODY_PACKAGE_SOURCE_HOSTS:-}
      # Webhooks + email (docs/webhooks.md, docs/email.md); empty = email off. compose.mail.yaml adds the SMTP bridge.
      KODY_WEBHOOK_MAX_BODY_BYTES: ${KODY_WEBHOOK_MAX_BODY_BYTES:-}
      KODY_EMAIL_DOMAIN: ${KODY_EMAIL_DOMAIN:-}
      KODY_EMAIL_INBOUND_TOKEN: ${KODY_EMAIL_INBOUND_TOKEN:-}
      KODY_EMAIL_MAILGUN_SIGNING_KEY: ${KODY_EMAIL_MAILGUN_SIGNING_KEY:-}
      KODY_EMAIL_OUTBOUND_PROVIDER: ${KODY_EMAIL_OUTBOUND_PROVIDER:-}
      KODY_EMAIL_OUTBOUND_URL: ${KODY_EMAIL_OUTBOUND_URL:-}
      KODY_EMAIL_OUTBOUND_TOKEN: ${KODY_EMAIL_OUTBOUND_TOKEN:-}
      KODY_EMAIL_MAILGUN_DOMAIN: ${KODY_EMAIL_MAILGUN_DOMAIN:-}
      KODY_EMAIL_FROM_NAME: ${KODY_EMAIL_FROM_NAME:-}
      KODY_EMAIL_TIMEOUT_MS: ${KODY_EMAIL_TIMEOUT_MS:-}
      KODY_EMAIL_MAX_BYTES: ${KODY_EMAIL_MAX_BYTES:-}
      KODY_QUOTA_EMAIL_MESSAGES: ${KODY_QUOTA_EMAIL_MESSAGES:-}
      KODY_QUOTA_EMAIL_SENDS_PER_DAY: ${KODY_QUOTA_EMAIL_SENDS_PER_DAY:-}
      KODY_QUOTA_EMAIL_RECEIVES_PER_DAY: ${KODY_QUOTA_EMAIL_RECEIVES_PER_DAY:-}
      KODY_SECRET_PROVIDER_CACHE_SECONDS: ${KODY_SECRET_PROVIDER_CACHE_SECONDS:-}
      KODY_SECRET_PROVIDER_TIMEOUT_MS: ${KODY_SECRET_PROVIDER_TIMEOUT_MS:-}
    volumes:
      - kody-data:/data
    extra_hosts:
      - 'host.docker.internal:host-gateway'

volumes:
  kody-data:

import { defineConfig, devices } from '@playwright/test'

/**
 * E2E suite — automates the browser-checkable parts of
 * manual-test-checklist.md. Camera and microphone come from Chromium's fake
 * media stack, so recording, editing, playback, and export all run for real
 * (only true hardware behavior — torch, zoom optics, share sheets — stays
 * on the manual list).
 *
 * Run: npm run test:e2e
 */
const PORT = 4189

export default defineConfig({
  testDir: 'tests/e2e',
  fullyParallel: true,
  // Recording + export tests do real encoding work.
  timeout: 90_000,
  expect: { timeout: 10_000 },
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? [['list'], ['github']] : [['list']],
  use: {
    baseURL: `http://127.0.0.1:${PORT}`,
    trace: 'retain-on-failure',
    permissions: ['camera', 'microphone'],
    launchOptions: {
      args: [
        '--use-fake-ui-for-media-stream',
        '--use-fake-device-for-media-stream',
        '--autoplay-policy=no-user-gesture-required',
        // Headless CI has no mDNS: without this, WebRTC host candidates are
        // *.local names the other context cannot resolve (send-to-device).
        '--disable-features=WebRtcHideLocalIpsWithMdns',
      ],
    },
  },
  projects: [
    {
      name: 'mobile',
      use: {
        ...devices['Pixel 7'],
        // Mouse-driven pointer events: the app listens to pointerdown, and
        // desktop-style input keeps hold/drag gestures deterministic.
        isMobile: false,
        hasTouch: false,
        defaultBrowserType: 'chromium',
      },
      testIgnore: [/desktop-keyboard/, /orientation-touch/],
    },
    {
      // Real touch emulation (pointer: coarse): the rotate-to-choose
      // orientation flow only exists on devices that are physically held.
      // Input still drives through the mouse (pointer events fire the same).
      name: 'touch',
      use: { ...devices['Pixel 7'], defaultBrowserType: 'chromium' },
      testMatch: /orientation-touch/,
    },
    {
      name: 'desktop',
      use: { ...devices['Desktop Chrome'], viewport: { width: 1100, height: 800 } },
      testMatch: /desktop-keyboard/,
    },
  ],
  webServer: {
    // Dev server (not preview): specs seed state by importing /src modules
    // in-page, which needs vite transforms.
    command: `npm run dev -- --host 127.0.0.1 --port ${PORT}`,
    url: `http://127.0.0.1:${PORT}`,
    reuseExistingServer: !process.env.CI,
    timeout: 30_000,
  },
})

import { copyFile, writeFile } from 'node:fs/promises'
import { defineConfig } from 'vite'
import { VitePWA } from 'vite-plugin-pwa'
import { sentryVitePlugin } from '@sentry/vite-plugin'
import { syncApiPlugin } from './scripts/vite-sync-api-plugin'

// Cloudflare Pages exposes the commit; local builds tag as 'dev'.
const commitSha = process.env.CF_PAGES_COMMIT_SHA ?? 'dev'
// Source maps upload only when the CI token is present (Cloudflare Pages env).
const sentryUpload = Boolean(process.env.SENTRY_AUTH_TOKEN)

export default defineConfig({
  define: {
    __COMMIT_SHA__: JSON.stringify(commitSha),
    __BUILD_DATE__: JSON.stringify(new Date().toISOString()),
  },
  build: {
    // Open-source app: ship public source maps for DevTools / PSI, and still
    // upload the same maps to Sentry when the CI token is present.
    sourcemap: true,
    // Modern baselines only — matches Vite 7 defaults; keeps transforms lean.
    target: ['chrome107', 'edge107', 'firefox104', 'safari16'],
  },
  esbuild: {
    jsx: 'automatic',
    jsxImportSource: 'remix/component',
  },
  plugins: [
    syncApiPlugin(),
    ...(sentryUpload
      ? [
          sentryVitePlugin({
            org: 'kent-c-dodds-tech-llc',
            project: 'kody-video',
            release: { name: commitSha },
            // Keep *.map in the Pages deploy so browsers can fetch them.
            sourcemaps: { filesToDeleteAfterUpload: [] },
          }),
        ]
      : []),
    {
      // First paint / LCP use inline critical CSS in index.html only. Strip
      // any Vite-injected stylesheet links so lantern does not model a
      // style-related LCP render delay; full CSS arrives via dynamic import()
      // from main.tsx. Defer the module entry by two frames so the LCP image
      // can paint before the main bundle evaluates.
      name: 'lcp-first-paint',
      transformIndexHtml(html) {
        const withoutCssLinks = html
          .replace(/<link rel="stylesheet"[^>]*>/g, '')
          .replace(/<link[^>]*as="style"[^>]*>/g, '')
          .replace(/<noscript><link rel="stylesheet"[^>]*><\/noscript>/g, '')
        return withoutCssLinks.replace(
          /<script type="module" crossorigin src="([^"]+)"><\/script>/,
          // The entry import must self-heal. Two failure classes, both seen
          // in production on 2026-08-05:
          //  1. A client kept the previous shell (installed PWA resuming
          //     across a deploy) and boots a retired hashed entry URL; the
          //     SPA fallback answers it with HTML, so import() dies on the
          //     MIME type and the app never mounts.
          //  2. HTTP-cache poisoning: during a deploy's edge-propagation
          //     window a hashed sub-chunk URL can answer with the SPA
          //     fallback HTML; the browser caches that body under the .js
          //     URL and 304 revalidation re-blesses it forever, so every
          //     boot fails on the same poisoned import.
          // Recovery: drop service workers + Cache Storage, then re-fetch
          // the shell and its whole asset graph with cache:"reload" (which
          // replaces poisoned HTTP-cache entries), and reload the page. A
          // timestamp cooldown (not a one-shot flag) keeps deploy-window
          // failures from hot-looping while still retrying a bit later.
          // lazy-page.tsx applies the same idea to route chunks.
          //
          // Installed / standalone: boot on this turn (no two-rAF LCP
          // delay) and never wipe the worker while offline — that is the
          // iOS white splash that never dismisses.
          `<script type="module">
            const src = "$1";
            const AT_KEY = "kody:boot-recover-at";
            const COOLDOWN_MS = 45000;
            const standalone =
              window.matchMedia("(display-mode: standalone)").matches ||
              navigator.standalone === true;
            const boot = () => {
