                  const queue = ["/", src];
                  while (queue.length && seen.size < 40) {
                    const url = queue.shift();
                    if (seen.has(url)) continue;
                    seen.add(url);
                    try {
                      const res = await fetch(url, { cache: "reload" });
                      const type = res.headers.get("content-type") ?? "";
